import {api} from '@/lib/client';
import type {Page} from '@/lib/types';
import {recordBalanceAdjustment} from '@/lib/customer-commerce';
import type {CanonicalOrder,CanonicalRechargeOrder,CanonicalOrderStatus} from '../../features/orders/types/order.types';
import type {WalletAdjustment} from '../../features/orders/types/wallet-adjustment.types';
import type {UserItem} from '../../features/users/types/user.types';
export type OrderRow={id:number;publicOrderId?:string;customerId:number;customerName?:string;gameName:string;packageName:string;playerId?:string;serverId?:string;quantity:number;unitPrice:number;sellPrice:number;status:string;manual:boolean;refunded:boolean;canRefund?:boolean;inputs?:Record<string,unknown>;createdAt:string;updatedAt:string};
export type RechargeRow={id:number;publicTransactionId:string;customerId:number;buyerName:string;email?:string;amount:number;requestedAmount:number;status:string;paymentDisplayName:string;createdAt:string;submittedAt?:string;reviewedAt?:string;receiptUrl?:string;adminNote?:string;hasReceipt:boolean;paymentAccount?:{accountName:string;accountNumber:string}};
type LedgerRow={id:number;customerId:number;customerName?:string;amount:number;beforeBalance:number;afterBalance:number;note?:string;createdAt:string};
type CustomerRow={id:number;userName:string;displayName:string;email:string;balance:number;enabled:boolean;createdAt:string};
export type Filter={size?:number;cursor?:string|null;search?:string;status?:string;startDate?:string;endDate?:string;historyMode?:boolean;includeTerminal?:boolean;awaitingPaymentOnly?:boolean};
const status=(s:string):CanonicalOrderStatus=>({SUCCESS:'Completed',PENDING:'Processing',PROCESSING:'Processing',FAILED:'Failed',REFUNDED:'Refunded',CANCELLED:'Cancelled',AWAITING_PAYMENT:'Pending',APPROVED:'Completed',REJECTED:'Cancelled',EXPIRED:'Cancelled'}[s] as CanonicalOrderStatus)||'Unknown';
export function duration(start?:string,end?:string,now=Date.now()){if(!start)return '—';const seconds=Math.max(0,Math.floor(((end?Date.parse(end):now)-Date.parse(start))/1000));return Number.isFinite(seconds)?`${Math.floor(seconds/60)}m ${seconds%60}s`:'—';}
export function businessTime(value?:string){if(!value)return '—';const d=new Date(value);return Number.isFinite(d.valueOf())?d.toLocaleString('en-US',{timeZone:'Asia/Yangon'}):'—';}
export function orderItem(r:OrderRow):CanonicalOrder {return {id:String(r.id),publicOrderId:r.publicOrderId,status:status(r.status),source:r.manual?'manual':'direct_topup',canResolveManualOrder:r.manual&&['PENDING','PROCESSING'].includes(r.status),username:r.customerName||`Customer #${r.customerId}`,buyerName:r.customerName,buyerCode:String(r.customerId),uid:[r.playerId,r.serverId&&`(${r.serverId})`].filter(Boolean).join(' ')||'—',packageName:r.packageName,price:Number(r.unitPrice),quantity:r.quantity,currency:'Ks',createdAt:r.createdAt,updatedAt:r.updatedAt,product:r.gameName,serverId:r.serverId,timeAgo:businessTime(r.createdAt),duration:duration(r.createdAt,['PENDING','PROCESSING'].includes(r.status)?undefined:r.updatedAt),orderInputs:Object.entries(r.inputs||{}).map(([key,value])=>({key,label:key,value:String(value??'')}))};}
export function rechargeItem(r:RechargeRow):CanonicalRechargeOrder{return {id:String(r.id),publicTransactionId:r.publicTransactionId,status:status(r.status),username:r.buyerName||`Customer #${r.customerId}`,buyerName:r.buyerName,buyerCode:String(r.customerId),amount:Number(r.amount),currency:'Ks',createdAt:r.createdAt,updatedAt:r.reviewedAt,paymentType:r.paymentDisplayName,isConfirmed:r.status==='APPROVED',isEditable:r.status==='PENDING'&&r.hasReceipt,receiptUrl:r.receiptUrl,userEmail:r.email,timeAgo:businessTime(r.createdAt),duration:duration(r.submittedAt,r.reviewedAt)};}
export function financeQuery(f:Filter,recharge=false){const page=f.cursor?Number(f.cursor.replace(/^page:/,'')):0;if(!Number.isSafeInteger(page)||page<0)throw Error('Invalid page.');const q=new URLSearchParams({page:String(page),size:String(f.size||10),q:(f.search||'').slice(0,100)});const st=(f.status||'all').toLowerCase();q.set('status',(recharge?({completed:'APPROVED',processing:'PENDING',cancelled:'CANCELLED'} as Record<string,string>)[st]:({completed:'SUCCESS',processing:'ACTIVE',active:'ACTIVE',failed:'FAILED',refunded:'REFUNDED'} as Record<string,string>)[st])||'ALL');if(recharge){q.set('visible',String(!f.awaitingPaymentOnly));if(f.awaitingPaymentOnly)q.set('status','AWAITING_PAYMENT');}if(f.startDate)q.set('startDate',f.startDate);if(f.endDate)q.set('endDate',f.endDate);return q;}
function cursorPage<T>(p:Page<T>){return {items:p.content,hasNext:!p.last&&p.number+1<p.totalPages,nextCursor:!p.last?`page:${p.number+1}`:null};}
async function all<T>(path:string){const rows:T[]=[];for(let page=0;page<1000;page++){const result=await api<Page<T>>(`${path}?page=${page}&size=100`);if(!Array.isArray(result.content))throw Error('Unable to read records.');rows.push(...result.content);if(result.last||page+1>=result.totalPages)return rows;}throw Error('Too many records to load at once. Please contact Main Admin.');}
function adjustment(r:LedgerRow):WalletAdjustment{return {id:String(r.id),userId:String(r.customerId),userName:r.customerName||`Customer #${r.customerId}`,type:Number(r.amount)>=0?'increase':'decrease',amount:Math.abs(Number(r.amount)),remark:r.note||'',createdAt:businessTime(r.createdAt)};}
export const adminPanelApi={
 orders:{page:async(f:Filter)=>{const p=await api<Page<OrderRow>>('customer-orders?'+financeQuery(f));return cursorPage({...p,content:p.content.map(orderItem)});}},
 topUps:{page:async(f:Filter)=>{const p=await api<Page<RechargeRow>>('recharges?'+financeQuery(f,true));return cursorPage({...p,content:p.content.map(rechargeItem)});}},
 users:{list:async():Promise<UserItem[]> =>(await all<CustomerRow>('customers')).map(c=>({id:String(c.id),username:c.userName,displayName:c.displayName,email:c.email,balance:Number(c.balance),status:c.enabled?'Active':'Disabled',createdAt:c.createdAt}))},
 adjustments:{list:async()=> (await all<LedgerRow>('balance-adjustments')).map(adjustment),create:async(value:Pick<WalletAdjustment,'userId'|'type'|'amount'|'remark'>,scope:{shop:string;owner:number})=>{
  const id=Number(value.userId),amount=Number(value.amount),note=value.remark?.trim()||'';
  if(!Number.isSafeInteger(id)||id<1||!Number.isFinite(amount)||amount<=0||!note)throw Error('Choose a user and enter a positive amount and reason.');
  const row=await recordBalanceAdjustment(scope.shop,scope.owner,id,{amount:value.type==='decrease'?-amount:amount,note});return adjustment(row as LedgerRow);
 }}
};
